create or replace function public.crm_sync_outbox_message_delivery() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status in ('sent','failed','dead_letter') and (old.status is distinct from new.status or old.external_message_id is distinct from new.external_message_id) then update public.crm_messages set external_message_id=coalesce(new.external_message_id,external_message_id),delivered_at=case when new.status='sent' then coalesce(delivered_at,now()) else delivered_at end,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('delivery_status',new.status,'last_error',new.last_error,'outbox_id',new.id) where channel_account_id=new.channel_account_id::text and metadata->>'outbox_id'=new.id::text and user_id=new.user_id; end if; return new; end; $$;
drop trigger if exists trg_crm_outbox_message_delivery_sync on public.crm_channel_message_outbox;
create trigger trg_crm_outbox_message_delivery_sync after update of status,external_message_id,last_error on public.crm_channel_message_outbox for each row execute function public.crm_sync_outbox_message_delivery();
revoke all on function public.crm_sync_outbox_message_delivery() from public,anon,authenticated;
grant execute on function public.crm_sync_outbox_message_delivery() to service_role;
